121	+/// The tool results of the transfer calls of one handoff, in call order.
122	+///
123	+/// `started` tells whether the target agent's `run` returned `Ok`. When it
124	+/// did, the first call gets `transferred to {target}`, and each other call
125	+/// of the same response gets a "transfer not performed" text. When it did
126	+/// not, every call gets `transfer failed: {target} did not start`. The text
127	+/// holds no error detail, because the result goes to a model.
128	+fn transfer_results(call_ids: &[String], target: &str, started: bool) -> Vec<crate::Item> {
129	+    call_ids
130	+        .iter()
131	+        .enumerate()
132	+        .map(|(i, call_id)| {
133	+            let text = if !started {
134	+                format!("transfer failed: {target} did not start")
135	+            } else if i == 0 {
136	+                format!("transferred to {target}")
137	+            } else {
138	+                format!("transfer not performed: this response already transferred to {target}")
139	+            };
140	+            crate::Item::ToolResult {
141	+                call_id: call_id.clone(),
142	+                content: vec![crate::ContentPart::Text { text }],
143	+            }
144	+        })
145	+        .collect()
146	+}
