188	+fn call(call_id: &str, tool: &str) -> ModelEvent {
189	+    ModelEvent::ToolCallDelta {
190	+        call_id: call_id.to_owned(),
191	+        name: Some(tool.to_owned()),
192	+        args_delta: "{}".to_owned(),
193	+    }
194	+}
