196	+/// One response with a call per `(call_id, tool)` pair.
197	+fn calls_turn(calls: &[(&str, &str)]) -> Vec<ModelEvent> {
198	+    let mut turn: Vec<ModelEvent> = calls.iter().map(|(id, tool)| call(id, tool)).collect();
199	+    turn.push(ModelEvent::Finish {
200	+        reason: FinishReason::ToolCalls,
201	+    });
202	+    turn
203	+}
204	+
205	+fn transfer_turn(call_id: &str, target: &str) -> Vec<ModelEvent> {
206	+    calls_turn(&[(call_id, &format!("transfer_to_{target}"))])
207	+}
