209	+fn text_turn(text: &str) -> Vec<ModelEvent> {
210	+    vec![
211	+        ModelEvent::TokenDelta {
212	+            text: text.to_owned(),
213	+        },
214	+        ModelEvent::Finish {
215	+            reason: FinishReason::Stop,
216	+        },
217	+    ]
