238	+/// Run `root` with a session recorder. Returns the events and the drained log.
239	+async fn recorded_run(
240	+    root: &impl Agent<()>,
241	+    ctx: RunContext<()>,
242	+) -> (Vec<AgentEvent>, Vec<SessionEvent>) {
243	+    let mut recorder = SessionRecorder::new(root.name());
244	+    let input = AgentInput::from_user_text("hi");
245	+    recorder.record_input(&input.messages);
246	+    let events: Vec<AgentEvent> = root
247	+        .run(ctx, input)
248	+        .await
249	+        .expect("run starts")
250	+        .collect()
251	+        .await;
252	+    for ev in &events {
253	+        recorder.observe(ev);
254	+    }
255	+    (events, recorder.drain())
256	+}
