258	+async fn run_with_session(root: &impl Agent<()>) -> (Vec<AgentEvent>, Vec<SessionEvent>) {
259	+    let session = Arc::new(MemorySession::new());
260	+    recorded_run(root, session_ctx(&session)).await
261	+}
