263	+// ── Helpers ──────────────────────────────────────────────────────────────────
264	+
265	+fn text_of(content: &[ContentPart]) -> String {
266	+    content
267	+        .iter()
268	+        .map(|p| match p {
269	+            ContentPart::Text { text } => text.clone(),
270	+            other => format!("{other:?}"),
271	+        })
272	+        .collect()
273	+}
