275	+/// Every `ToolOutputItem` as `(call_id, text)`, in event order.
276	+fn outputs(events: &[AgentEvent]) -> Vec<(String, String)> {
277	+    events
278	+        .iter()
279	+        .filter_map(|e| match e {
280	+            AgentEvent::ToolOutputItem {
281	+                item: Item::ToolResult { call_id, content },
282	+            } => Some((call_id.clone(), text_of(content))),
283	+            _ => None,
284	+        })
285	+        .collect()
286	+}
