288	+/// A short label per event kind, for order checks.
289	+fn kind(e: &AgentEvent) -> String {
290	+    match e {
291	+        AgentEvent::ToolCallItem {
292	+            item: Item::ToolCall { call_id, .. },
293	+        } => format!("call({call_id})"),
294	+        AgentEvent::ToolOutputItem {
295	+            item: Item::ToolResult { call_id, .. },
296	+        } => format!("output({call_id})"),
297	+        AgentEvent::HandoffItem { to, .. } => format!("handoff({to})"),
298	+        AgentEvent::AgentUpdated { agent } => format!("updated({agent})"),
299	+        AgentEvent::RunFailed { .. } => "failed".to_owned(),
300	+        _ => "other".to_owned(),
301	+    }
302	+}
303	+
304	+fn kinds(events: &[AgentEvent]) -> Vec<String> {
305	+    events.iter().map(kind).filter(|k| k != "other").collect()
306	+}
307	+
308	+/// A short label per session event.
309	+fn label(e: &SessionEvent) -> String {
310	+    match e {
311	+        SessionEvent::UserMessage { .. } => "user".to_owned(),
312	+        SessionEvent::AssistantMessage { agent, .. } => format!("assistant({agent})"),
313	+        SessionEvent::ToolCalled { call_id, .. } => format!("tool_called({call_id})"),
314	+        SessionEvent::ToolReturned {
315	+            call_id, content, ..
316	+        } => format!("tool_returned({call_id}, {})", text_of(content)),
317	+        SessionEvent::HandoffOccurred { to, .. } => format!("handoff({to})"),
318	+        other => format!("{other:?}"),
319	+    }
320	+}
321	+
322	+fn labels(log: &[SessionEvent]) -> Vec<String> {
323	+    log.iter().map(label).collect()
324	+}
