326	+/// No transfer result for `call_id` and no `transferred` text anywhere.
327	+fn assert_no_transfer_result(events: &[AgentEvent], call_id: &str) {
328	+    let outs = outputs(events);
329	+    assert!(
330	+        !outs.iter().any(|(id, _)| id == call_id),
331	+        "no ToolOutputItem for {call_id}: {outs:?}"
332	+    );
333	+    assert!(
334	+        !outs.iter().any(|(_, t)| t.starts_with("transferred")),
335	+        "no transferred text: {outs:?}"
336	+    );
337	+    assert!(
338	+        matches!(events.last(), Some(AgentEvent::RunFailed { .. })),
339	+        "{events:?}"
340	+    );
341	+}
342	+
343	+/// Each `ToolCall` has a `ToolResult` with the same call id later, with no
344	+/// `UserMessage` or `AssistantMessage` between them. Each `ToolResult` closes
345	+/// one earlier open `ToolCall` with its call id. A call id can repeat only
346	+/// after its earlier call has a result. A call after a result starts a new
347	+/// round, so no call may wait for a result then.
348	+fn assert_tool_calls_paired(messages: &[Item]) {
349	+    let mut outstanding: Vec<&str> = Vec::new();
350	+    let mut seen_result_since_call = false;
351	+    for item in messages {
352	+        match item {
353	+            Item::ToolCall { call_id, .. } => {
354	+                assert!(
355	+                    !outstanding.contains(&call_id.as_str()),
356	+                    "call {call_id} repeats while it waits for a result: {messages:?}"
357	+                );
358	+                assert!(
359	+                    !(seen_result_since_call && !outstanding.is_empty()),
360	+                    "call {call_id} starts a new round while {outstanding:?} wait for a result: {messages:?}"
361	+                );
362	+                seen_result_since_call = false;
363	+                outstanding.push(call_id);
364	+            }
365	+            Item::ToolResult { call_id, .. } => {
366	+                let Some(p) = outstanding.iter().position(|c| *c == call_id.as_str()) else {
367	+                    panic!("result {call_id} has no open earlier call: {messages:?}");
368	+                };
369	+                outstanding.remove(p);
370	+                seen_result_since_call = true;
371	+            }
372	+            Item::UserMessage { .. } | Item::AssistantMessage { .. } => {
373	+                assert!(
374	+                    outstanding.is_empty(),
375	+                    "tool calls {outstanding:?} are not paired: {messages:?}"
376	+                );
377	+            }
378	+            _ => {}
379	+        }
380	+    }
381	+    assert!(
382	+        outstanding.is_empty(),
383	+        "tool calls {outstanding:?} are not paired: {messages:?}"
384	+    );
385	+}
